public async Task<string> ReadWithTaskAsync(string key)
{
    // Even on cache hit, a Task<string> is allocated.
    return await _cache.GetAsync(key);
}

public async ValueTask<string> ReadWithValueTaskAsync(string key)
{
    // On cache hit: returns ValueTask<string> with cached result.
    // On cache miss: wraps the underlying Task<string>.
    return await _cache.GetAsync(key).ConfigureAwait(false);
}

